using Rhino; using Rhino.DocObjects; using Rhino.Geometry;
namespace RhinoContextAssist;
internal static class SelectionAnalyzer{
 public static SelectionContext Analyze(RhinoDoc doc){var selected=doc.Objects.GetSelectedObjects(false,false).ToList();if(selected.Count==0)selected=doc.Objects.Where(o=>o.GetSelectedSubObjects()?.Length>0).ToList();if(selected.Count==0)return new(SelectionKind.None,0,"Keine Auswahl",Point3d.Unset);var anchor=UnionBox(selected).Center;if(selected.Count==1){var obj=selected[0];var sub=obj.GetSelectedSubObjects();if(sub is{Length:>0}){var ci=sub[0];var brep=AsBrep(obj);if(ci.ComponentIndexType==ComponentIndexType.BrepFace&&brep!=null&&ci.Index>=0&&ci.Index<brep.Faces.Count){var f=brep.Faces[ci.Index];anchor=f.GetBoundingBox(true).Center;return f.TryGetPlane(out _)?new(SelectionKind.PlanarBrepFace,1,"Planare Teilfläche",anchor):new(SelectionKind.BrepFace,1,"Teilfläche",anchor);}if(ci.ComponentIndexType==ComponentIndexType.BrepEdge&&brep!=null&&ci.Index>=0&&ci.Index<brep.Edges.Count){anchor=brep.Edges[ci.Index].GetBoundingBox(true).Center;return new(SelectionKind.BrepEdge,1,"Brep-Kante",anchor);}}return AnalyzeObject(obj,anchor);}var kinds=selected.Select(o=>AnalyzeObject(o,anchor).Kind).Distinct().ToList();return kinds.Count==1?new(SelectionKind.Multiple,selected.Count,$"{selected.Count} Objekte",anchor):new(SelectionKind.Mixed,selected.Count,$"{selected.Count} gemischte Objekte",anchor);}
 static BoundingBox UnionBox(List<RhinoObject> objects){var box=BoundingBox.Empty;foreach(var o in objects)box.Union(o.Geometry.GetBoundingBox(true));return box;}
 static Brep? AsBrep(RhinoObject o)=>o.Geometry switch{Brep b=>b,Extrusion e=>e.ToBrep(),_=>null};
 static SelectionContext AnalyzeObject(RhinoObject o,Point3d a)=>o.Geometry switch{Curve c when c.IsClosed&&c.IsPlanar()=>new(SelectionKind.ClosedPlanarCurve,1,"Geschlossene planare Kurve",a),Curve=>new(SelectionKind.Curve,1,"Kurve",a),Brep b when b.Faces.Count==1&&b.Faces[0].TryGetPlane(out _)=>new(SelectionKind.PlanarSurface,1,"Planare Fläche",a),Brep b when b.Faces.Count==1=>new(SelectionKind.Surface,1,"Fläche",a),Brep b when b.IsSolid=>new(SelectionKind.SolidBrep,1,"Geschlossener Körper",a),Brep=>new(SelectionKind.Brep,1,"Flächenverband",a),Extrusion e when e.IsSolid=>new(SelectionKind.SolidBrep,1,"Geschlossene Extrusion",a),Extrusion=>new(SelectionKind.Surface,1,"Extrusion",a),Mesh=>new(SelectionKind.Mesh,1,"Mesh",a),SubD=>new(SelectionKind.SubD,1,"SubD",a),_=>new(SelectionKind.Multiple,1,o.ObjectType.ToString(),a)};}
